#!/usr/bin/env bash
set -euo pipefail
APP="$(pwd)/build/install/vericore/bin/vericore"
PORT="18080"
LOG="/tmp/vericore-rest-audit.log"
SERVER_WORKDIR="$(mktemp -d)"
# Isolate server configuration from any project config generated by earlier audit
# steps, and use a small explicit budget so this regression is fast and deterministic.
cat >"$SERVER_WORKDIR/.vericore.json" <<'JSON'
{
  "rateLimit": {
    "enabled": true,
    "requestsPerMinute": 10,
    "requestsPerHour": 20
  }
}
JSON
(
  cd "$SERVER_WORKDIR"
  exec "$APP" server --host 127.0.0.1 --port "$PORT"
) >"$LOG" 2>&1 &
PID=$!
cleanup(){ kill "$PID" 2>/dev/null || true; wait "$PID" 2>/dev/null || true; rm -rf "$SERVER_WORKDIR"; }
trap cleanup EXIT
for _ in $(seq 1 30); do if curl -fsS "http://127.0.0.1:${PORT}/health" >/tmp/vericore-health.json 2>/dev/null; then break; fi; sleep 1; done
curl -fsS "http://127.0.0.1:${PORT}/" >/tmp/vericore-root.json
curl -fsS "http://127.0.0.1:${PORT}/health" >/tmp/vericore-health.json
curl -fsS "http://127.0.0.1:${PORT}/health/live" >/tmp/vericore-live.json
curl -fsS "http://127.0.0.1:${PORT}/health/ready" >/tmp/vericore-ready.json
status=$(curl -sS -o /tmp/vericore-invalid.json -w '%{http_code}' -X POST "http://127.0.0.1:${PORT}/analyze" -H 'Content-Type: application/json' -d '{"repoPath":"https://github.com/example/example.git"}')
if [[ "$status" =~ ^2|^3 ]]; then echo "REST security audit failed: remote repository URL accepted" >&2; exit 1; fi

# The unauthenticated REST service must refuse non-loopback binding unless the
# caller uses the explicit unsafe opt-in. Never start a listener for this check.
if "$APP" server --host 0.0.0.0 --port 18081 >/tmp/vericore-remote-bind-denied.log 2>&1; then
  echo "REST security audit failed: non-loopback bind was accepted without opt-in" >&2
  exit 1
fi
grep -q "Refusing non-loopback host" /tmp/vericore-remote-bind-denied.log

# X-API-Key is not authentication. Sending a unique value on every request must
# not create fresh rate-limit buckets and bypass the per-peer request budget.
saw_throttle=false
for i in $(seq 1 70); do
  code=$(curl -sS -o /dev/null -w '%{http_code}' -H "X-API-Key: unverified-$i" "http://127.0.0.1:${PORT}/health")
  if [[ "$code" == "429" ]]; then
    saw_throttle=true
    break
  fi
done
if [[ "$saw_throttle" != "true" ]]; then
  echo "REST security audit failed: caller-controlled X-API-Key bypassed per-peer rate limiting" >&2
  exit 1
fi

python3 - <<'PY'
import json
from pathlib import Path
root_text=Path('/tmp/vericore-root.json').read_text()
root=json.loads(root_text) if root_text.lstrip().startswith('{') else None
health=json.loads(Path('/tmp/vericore-health.json').read_text())
version_source=Path('src/main/kotlin/com/vericore/core/Version.kt').read_text()
expected=version_source.split('const val current: String = "', 1)[1].split('"', 1)[0]
assert health.get('status') == 'healthy'
assert health.get('version') == expected, (health.get('version'), expected)
PY
echo "REST audit: PASS"
